const prompts = [
  ["Price only", "Use only these hypothetical facts: Oak costs $160; Birch costs $110; budget ceiling is $120. Compare price only, distinguishing the cheaper option from the one within budget. No browsing, messages, mutations, scheduling, or tools. Return a concise finding and price arithmetic."],
  ["Time only", "Use only these hypothetical facts: Oak takes 30 minutes; Birch takes 60 minutes. Compare time only. No browsing, messages, mutations, scheduling, or tools. Return a concise finding and time difference." ]
];
const settled = await Promise.allSettled(prompts.map(([label,prompt]) => agents.run(prompt,{agentId:"plow-worker",label})));
text(settled.map((r,i)=>({lane:prompts[i][0],status:r.status,result:r.status==="fulfilled"?r.value:String(r.reason)})));
